/bin/zsh -lc "python3 -c 'import os, pathlib, hashlib, json
root=pathlib.Path.cwd()
print('\\''ROOT_ENTRIES'\\'', json.dumps(sorted(p.name for p in root.iterdir())))
for scope in ('\\''ops'\\'','\\''src'\\'','\\''.tmpl.docs'\\''):
    for base, dirs, files in os.walk(root/scope, followlinks=False):
        dirs.sort(); files.sort()
        for name in dirs+files:
            p=pathlib.Path(base)/name
            if p.is_symlink(): print('\\''SYMLINK_EXCLUDED'\\'',p.relative_to(root))
        dirs[:]=[d for d in dirs if not (pathlib.Path(base)/d).is_symlink()]
        for name in files:
            p=pathlib.Path(base)/name
            if p.is_symlink() or not p.is_file(): continue
            print('\\''ENTRY'\\'',p.relative_to(root))
            if scope=='\\''.tmpl.docs'\\'': continue
            data=p.read_bytes()
            print('\\''FILE'\\'',str(p.relative_to(root)),'\\''SHA256'\\'',hashlib.sha256(data).hexdigest())
            for n,line in enumerate(data.decode('\\''utf-8'\\'').splitlines(),1): print(f'\\''{n:4}: {line}'\\'')
for rel in ('\\''AGENTS.md'\\'','\\''.agents/skills/egm-drift-report/SKILL.md'\\'','\\''docs/agents/runtime.md'\\'','\\''docs/agents/drift-report.md'\\'','\\''docs/agents/codex.md'\\''):
    p=root/rel; data=p.read_bytes()
    print('\\''RULE_HASH'\\'',rel,hashlib.sha256(data).hexdigest())
    if rel=='\\''AGENTS.md'\\'':
        for n,line in enumerate(data.decode().splitlines(),1): print(f'\\''{n:4}: {line}'\\'')
'"

